import {IDS,KEY,emptyState,validateState,mergeState,routine,thermal,flags,timing,readings,above,pipeline} from './engine.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let state=emptyState(),storageAvailable=true,noticeTimer;
function notify(text){const n=$('#notice');n.textContent=text;n.classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>n.classList.remove('show'),5000);}
try{const raw=localStorage.getItem(KEY);if(raw)state=validateState(JSON.parse(raw));}catch{storageAvailable=false;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageAvailable=false;notify('Your browser could not save progress. Export a backup to keep it.');}}
function dateKey(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
let data;
try{const response=await fetch('/coding_assets/data.json');if(!response.ok)throw Error();data=await response.json();}catch{notify('Interactive content could not load. The full guides and resource links are still available.');}
function renderPractice(){
 const m=routine(state.minutes);if($('#routine'))$('#routine').innerHTML=`<div><strong>${m.recall} min</strong>Recall & predict</div><div><strong>${m.code} min</strong>Write & test code</div><div><strong>${m.explain} min</strong>Explain & save</div>`;
 $$('[data-minutes]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.minutes)===state.minutes)));
 if($('#focus'))$('#focus').value=state.focus;
 const language=data?.languages.find(l=>l.id===state.focus);if(language&&$('#first-task'))$('#first-task').textContent=language.first;
 const days=Object.keys(state.sessions).filter(k=>state.sessions[k].length).length,done=state.sessions[dateKey()]?.includes(state.focus);
 if($('#practice-count'))$('#practice-count').textContent=storageAvailable?`${days} practice ${days===1?'day':'days'} recorded in this browser. ${done?'Today’s focus is recorded.':'One focused session is enough.'}`:'Storage is unavailable. You can still practice and export a backup.';
 if($('#log-session')){$('#log-session').disabled=!!done;$('#log-session').textContent=done?'Today’s practice recorded ✓':'Record today’s practice ✓';}
}
if(IDS.includes(document.body.dataset.language))state.focus=document.body.dataset.language;
renderPractice();
$$('[data-minutes]').forEach(b=>b.addEventListener('click',()=>{state.minutes=Number(b.dataset.minutes);save();renderPractice();}));
$('#focus')?.addEventListener('change',e=>{state.focus=e.target.value;save();renderPractice();});
$('#log-session')?.addEventListener('click',()=>{const k=dateKey();state.sessions[k]=[...new Set([...(state.sessions[k]||[]),state.focus])];save();renderPractice();notify('Practice recorded. Keep a small piece of code you can explain.');});
function renderChecks(){let checked=0;$$('[data-check]').forEach(c=>{c.checked=!!state.checks[c.dataset.check];if(c.checked)checked++;});if($('#mastery-count'))$('#mastery-count').textContent=`${checked} of 4 readiness checks marked. These are self-assessments saved in this browser.`;}
renderChecks();$$('[data-check]').forEach(c=>c.addEventListener('change',()=>{state.checks[c.dataset.check]=c.checked;save();renderChecks();}));
$('#export-progress')?.addEventListener('click',()=>{const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`coding-progress-${dateKey()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);notify('Backup exported. Keep it somewhere you can find later.');});
$('#import-button')?.addEventListener('click',()=>$('#import-progress').click());
$('#import-progress')?.addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>500000)throw Error('Backup is too large. Choose a Coding Field Guide JSON backup.');state=mergeState(state,JSON.parse(await file.text()));save();renderPractice();renderChecks();notify('Backup imported. Recognized progress was merged.');}catch(err){notify(err.message||'Could not read this backup. Existing progress is unchanged.');}finally{e.target.value='';}});
$$('[data-mission]').forEach(b=>b.addEventListener('click',()=>{const m=data?.missions[b.dataset.mission];if(!m)return;$$('[data-mission]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#mission-tag').textContent=m.tag;$('#mission-title').textContent=m.title;$('#mission-description').textContent=m.description;const list=$('#mission-parts');list.replaceChildren();m.parts.forEach((p,i)=>{const li=document.createElement('li'),span=document.createElement('span');span.textContent=data.languages[i].symbol;li.append(span,document.createTextNode(p));list.append(li);});}));
$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{const f=b.dataset.filter;$$('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));let count=0;$$('.resource').forEach(r=>{const visible=f==='all'||r.dataset.tier===f||((f==='free'||f==='paid')&&r.dataset[f]==='true');r.hidden=!visible;if(visible)count++;});$('#filter-count').textContent=`Showing ${count} ${count===1?'resource':'resources'}.`;}));
$$('.copy-code').forEach(b=>b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(b.closest('.code-panel').querySelector('code').textContent);notify('Example copied. Run it in the matching language environment.');}catch{notify('Clipboard access was unavailable. Select the code and copy it manually.');}}));
const lab=$('[data-lab]');
function renderLab(){if(!lab)return;const id=lab.dataset.lab,v=$('#lab-input').value,display=$('#lab-display'),result=$('#lab-result'),output=$('#lab-value');
 if(id==='python'){const n=Number(v);output.textContent=`${n} °C`;display.innerHTML=`<div class="telemetry-bars">${readings.map(r=>`<div class="${r>n?'flagged':''}" style="height:${r/40*100}%"><span>${r}°</span></div>`).join('')}</div><div class="telemetry-labels"><span>Sample 1</span><span>Sample 2</span><span>Sample 3</span><span>Sample 4</span></div>`;result.textContent=`${above(n).length} of 4 readings exceed ${n} °C. “Exceed” uses >, so a value equal to the threshold is not flagged.`;}
 if(id==='cpp'){const n=Number(v),t=timing(n);output.textContent=`${n} ms`;display.innerHTML=`<div class="meter"><span class="${t.over?'over':''}" style="width:${Math.min(100,n/20*100)}%"></span></div><div class="metric-row"><span>0 ms</span><span>20 ms update interval</span></div>`;result.textContent=t.over?`Over budget by ${-t.remaining} ms. The next update would already be due.`:`${t.remaining} ms of budget remains before accounting for other work and variability.`;}
 if(id==='matlab'){const n=Number(v);output.textContent=`${n} s`;const points=Array.from({length:121},(_,t)=>`${40+t*3.5},${175-(thermal(t,n)-20)*6}`).join(' ');display.innerHTML=`<svg class="chart" viewBox="0 0 500 220" role="img" aria-label="Cooling curve from 40 degrees toward 20 degrees Celsius over 120 seconds"><g stroke="#b5cbbb" stroke-width="1"><path d="M40 30V175H460M40 55H460M40 115H460" fill="none"/></g><polyline points="${points}" fill="none" stroke="#27674d" stroke-width="3"/><g font-size="11" fill="#3f6254" font-family="sans-serif"><text x="7" y="59">40°</text><text x="7" y="119">30°</text><text x="7" y="179">20°</text><text x="37" y="195">0</text><text x="243" y="195">60</text><text x="446" y="195">120</text><text x="205" y="213">Time (seconds)</text></g></svg>`;result.textContent=`At 60 s: ${thermal(60,n).toFixed(2)} °C. At one time constant (${n} s), about 63.2% of the initial temperature difference has disappeared.`;}
 if(id==='c'){const n=Number(v),f=flags(n);output.textContent=String(n);display.innerHTML=`<div class="bits" aria-label="Binary ${f.binary}">${[...f.binary].map(bit=>`<span class="bit ${bit==='1'?'on':''}">${bit}</span>`).join('')}</div>`;result.textContent=`Fault: ${f.fault?'YES':'no'} · Stale data: ${f.stale?'YES':'no'} · Low battery: ${f.battery?'YES':'no'}. Least-significant bit is on the right.`;}
 if(id==='bash'){display.replaceChildren();const pre=document.createElement('pre');pre.className='log-output';pre.textContent=pipeline(v);display.append(pre);result.textContent=v==='all'?'Five input lines. The source log is unchanged.':v==='warn'?'Two matching lines pass through the filter.':'The count is 2. The -c option asks grep to count matching lines.';}
}
$('#lab-input')?.addEventListener('input',renderLab);renderLab();
